pub fn printLimits() void {
            const LIMITS = .{ std.posix.rlimit_resource.STACK, std.posix.rlimit_resource.NOFILE };
            _ = Output.print("{{\n", .{});
            var i: usize = 0;
            _ = &i;
            for (cp_iter_slice(LIMITS)) |limit_type| {
                _ = &limit_type;
                const limit = (blk_catch_20: { break :blk_catch_20 ((std.posix.getrlimit(limit_type)) catch |__ce_20| { _ = &__ce_20; return; }); });
                if ((i == 0)) {
                    _ = Output.print("  \"stack\": [{d}, {d}],\n", .{ limit.cur, limit.max });
                } else {
                    if ((i == 1)) {
                        _ = Output.print("  \"files\": [{d}, {d}]\n", .{ limit.cur, limit.max });
                    }
                }
                i = (i + 1);
            }
            _ = Output.print("}}\n", .{});
            _ = Output.flush();
    }
