pub fn printHandle(handle: anytype) std.fmt.Alt(@TypeOf(handle),FmtHandleFnGenerator(@TypeOf(handle)).fmtHandle) {
        return .{ .data = handle };
}

pub fn FmtHandleFnGenerator(comptime T: type) type {
        return struct {

pub fn fmtHandle(handle: T, writer: *std.Io.Writer) std.Io.Writer.Error!void {
            if ((@TypeOf(handle) == i32) or (@TypeOf(handle) == c_int)) {
_ = try writer.print("{d}", .{ handle });
} else if (@TypeOf(handle) == *anyopaque) {
_ = try writer.print("{*}", .{ handle });
} else if (@TypeOf(handle) == FD) {
_ = try writer.print("{f}", .{ handle });
} else {
_ = @compileError(("unsupported type for fmtHandle: " ++ @typeName(T)));
}
    }
};
